import unittest

from solution import clamp_scaled


class ClampScaledTests(unittest.TestCase):
    def test_scales_before_clamping(self):
        self.assertEqual(clamp_scaled(4, 3, 10), 10.0)
        self.assertEqual(clamp_scaled(-4, 3, 10), -10.0)
        self.assertEqual(clamp_scaled(100, 0.05, 10), 5.0)

    def test_negative_factor_changes_clamp_side(self):
        self.assertEqual(clamp_scaled(4, -3, 10), -10.0)
        self.assertEqual(clamp_scaled(-4, -3, 10), 10.0)

    def test_inclusive_boundaries_and_zero_limit(self):
        self.assertEqual(clamp_scaled(2, 5, 10), 10.0)
        self.assertEqual(clamp_scaled(-2, 5, 10), -10.0)
        self.assertEqual(clamp_scaled(7, -4, 0), 0.0)

    def test_always_returns_float(self):
        self.assertEqual(clamp_scaled(2, 3, 10), 6.0)
        self.assertIsInstance(clamp_scaled(2, 3, 10), float)

    def test_invalid_types(self):
        for args in ((True, 1, 1), (1, False, 1), (1, 1, True), ("1", 1, 1), (1, None, 1)):
            with self.subTest(args=args), self.assertRaises(TypeError):
                clamp_scaled(*args)

    def test_non_finite_and_negative_limit(self):
        for args in ((float("nan"), 1, 1), (1, float("inf"), 1), (1, 1, float("-inf"))):
            with self.subTest(args=args), self.assertRaises(ValueError):
                clamp_scaled(*args)
        with self.assertRaises(ValueError):
            clamp_scaled(1, 1, -0.01)


if __name__ == "__main__":
    unittest.main()

